import { describe, expect, it } from "vitest";
import { createCapability, registerCapability, registeredCapabilities } from "@banes-lab/web";

describe("capability registry", () => {
    it("replaces rather than duplicates on the same id", () => {
        registerCapability(createCapability("telemetry"));
        registerCapability(createCapability("telemetry"));
        expect(registeredCapabilities().filter((c) => c.id === "telemetry")).toHaveLength(1);
    });
});
